    .reg .u32   %tid.x, %tid.y, %tid.z;
    .reg .u32   %blk.x, %blk.y, %blk.z;
    .reg .u32   %dim2, %dim1, %batch;
    .reg .u64   %in_ptr, %out_ptr;

