    mov.u32 %tid.x, %tid.x;
    mov.u32 %blk.x, %blk.x;
    mov.u32 %tid.y, %tid.y;
    mov.u32 %blk.y, %blk.y;

    // Compute global column index (dimension 2)
    mad.lo.u32 %tid.x, %blk.x, %ctaid.x, %tid.x;   // not needed, use built‑ins
    // Use PTX built‑ins
    mov.u32 %tid.x, %tid.x;          // threadIdx.x
    mov.u32 %blk.x, %blk.x;          // blockIdx.x
    mov.u32 %blk.y, %blk.y;          // blockIdx.y

    // col = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.u32 %tid.x, %blk.x, %ntid.x, %tid.x;
    // row (batch) = blockIdx.y
    mov.u32 %blk.y, %blk.y;

    // Bounds check
    setp.ge.u32   %p0, %tid.x, %dim2;
    setp.ge.u32   %p1, %blk.y, %batch;
    @%p0 bra DONE;
    @%p1 bra DONE;

    // Registers for loop
    .reg .u32   %i;
    .reg .u64   %addr;
    .reg .u32   %linear_idx;
    .reg .f16   %val;
    .reg .f16   %max_val;
    .reg .u32   %argmax;

